          "text": "Possible rotator cuff condition or shoulder impingement; does not explain the discrete numb area"
        },
        "verificationStatus": {
          "coding": [
            {
              "system": "http://terminology.hl7.org/CodeSystem/condition-ver-status",
              "code": "provisional"
            }
          ]
        }
      }
    },
