      "fullUrl": "https://example.org/fhir/Observation/observation-3",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-3",
        "status": "final",
        "code": {
          "text": "Pain onset and duration"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Onset unclear; initially described as 1–2 weeks, then as 'ages, at least a month'; timeline reported as unreliable."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-4",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-4",
        "status": "final",
        "code": {
          "text": "Left shoulder pain aggravating and relieving factors"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Worse lying on the left side, with abduction, overhead work and lifting tools. Heat pack helps a little; Panadol does nothing."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-5",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-5",
        "status": "final",
        "code": {
          "text": "Focal numbness over left upper outer shoulder"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Patient describes a 'dead patch' of numbness over the left upper outer shoulder, beginning a few days after the pain started."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-6",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-6",
        "status": "final",
        "code": {
          "text": "Subjective left arm weakness"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Reports struggling to lift a ladder and compensating with the right side."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-7",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-7",
        "status": "final",
        "code": {
          "text": "Possible contributors to shoulder pain"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No trauma recalled; wonders whether he slept 'funny on lounge' and reports using a new, heavier cordless drill at work."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-8",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-8",
        "status": "final",
        "code": {
          "text": "Negative symptoms: neck and distal upper limb"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Denies neck pain, shooting pain down the arm, tingling in the fingers, hand weakness and neck stiffness."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-9",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-9",
        "status": "final",
        "code": {
          "text": "Red flag screen"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Denies chest pain, shortness of breath, jaw pain, diaphoresis, fever, weight loss, night sweats, recent neck injury, limb heaviness or clumsiness, gait change, and sphincter disturbance."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-10",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-10",
        "status": "final",
        "code": {
          "text": "Telehealth examination findings"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No observations obtained. Voice comfortable at rest, with occasional pauses or winces when describing movement. Speech and cognition okay; vague about dates and contradictory about duration. No audible shortness of breath or cough."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-11",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-11",
        "status": "final",
        "code": {
          "text": "Chronic back ache"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Briefly reports chronic back ache, 'probably ute seats'; review deferred if ongoing."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationStatement/medication-statement-1",
      "resource": {
        "resourceType": "MedicationStatement",
        "id": "medication-statement-1",
        "status": "unknown",
        "medicationCodeableConcept": {
          "text": "Ibuprofen"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "note": [
          {
            "text": "Tried old ibuprofen a couple of times; dose unsure."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationStatement/medication-statement-2",
      "resource": {
        "resourceType": "MedicationStatement",
        "id": "medication-statement-2",
        "status": "unknown",
        "medicationCodeableConcept": {
          "text": "Panadol (paracetamol)"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "note": [
          {
            "text": "Reports trying Panadol for the pain; dose and frequency not stated. Says it does nothing."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationRequest/medication-request-1",
      "resource": {
        "resourceType": "MedicationRequest",
        "id": "medication-request-1",
        "status": "active",
        "intent": "order",
        "medicationCodeableConcept": {
          "text": "Prednisolone"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosageInstruction": [
          {
            "text": "50 mg orally in the morning for 5 days with food; short course. Avoid NSAIDs while taking prednisolone.",
            "route": {
              "text": "oral"
            },
            "timing": {
              "repeat": {
                "frequency": 1,
                "period": 1,
                "periodUnit": "d",
                "boundsDuration": {
                  "value": 5,
                  "unit": "days",
                  "code": "d",
                  "system": "http://unitsofmeasure.org"
                }
              }
            },
            "doseAndRate": [
              {
                "doseQuantity": {
                  "value": 50,
                  "unit": "mg"
                }
              }
            ]
          }
        ],
        "note": [
          {
            "text": "Warned about possible mood changes, insomnia and dyspepsia."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationRequest/medication-request-2",
      "resource": {
        "resourceType": "MedicationRequest",
        "id": "medication-request-2",
        "status": "active",
        "intent": "order",
        "medicationCodeableConcept": {
          "text": "Paracetamol"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosageInstruction": [
          {
            "text": "1 g four times daily as needed; maximum 4 g per day.",
            "asNeededBoolean": true,
            "timing": {
              "repeat": {
                "frequency": 4,
                "period": 1,
                "periodUnit": "d"
              }
            },
            "doseAndRate": [
              {
                "doseQuantity": {
                  "value": 1,
                  "unit": "g"
                }
              }
